#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* -------------------------------------------------------------
   Parse a decimal integer from a string using strtol.
   Success means:
        – at least one digit was consumed,
        – the whole string was consumed (no trailing characters).
   The function deliberately does **not** reject overflow, because the
   original program also accepted overflow values (they later trigger
   OUT_OF_RANGE or produce a result of 0).  It returns 1 on success,
   0 on failure.
   ------------------------------------------------------------- */
static int parse_long(const char *s, long *out)
{
    char *endptr;
    long val = strtol(s, &endptr, 10);

    /* No digits at all? */
    if (endptr == s)
        return 0;

    /* Trailing characters? */
    if (*endptr != '\0')
        return 0;

    *out = val;
    return 1;
}

/* -------------------------------------------------------------
   Compute the binomial coefficient C(n,k) for 0 ≤ n ≤ 60.
   Returns 0 when k<0 or k>n, matching the original recursive version.
   The result always fits into a signed 64‑bit integer for the allowed
   range of n.
   ------------------------------------------------------------- */
static long long binom(long long n, long long k)
{
    if (k < 0 || k > n)
        return 0;
    if (k == 0 || k == n)
        return 1;

    /* Use symmetry to minimise the number of iterations */
    if (k > n - k)
        k = n - k;

    long long res = 1;
    for (long long i = 1; i <= k; ++i) {
        /* The division is exact at each step */
        res = res * (n - k + i) / i;
    }
    return res;
}

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
       1) Argument count check – original prints "NO_INPUT" when argc<3.
       ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       2) Parse the two arguments with the same rules as the original.
       ----------------------------------------------------------------- */
    long n, k;
    if (!parse_long(argv[1], &n) || !parse_long(argv[2], &k)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* -----------------------------------------------------------------
       3) Range check for the first argument (n).  The original allowed
          only 0 ≤ n ≤ 60.
       ----------------------------------------------------------------- */
    if (n < 0 || n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
       4) Compute and print the binomial coefficient.
       ----------------------------------------------------------------- */
    long long result = binom(n, k);
    printf("%lld\n", result);
    return 0;
}
